import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"长任务与定时任务","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),e={name:"guide/tasks.md"};function i(n,t,s,d,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="长任务与定时任务" tabindex="-1">长任务与定时任务 <a class="header-anchor" href="#长任务与定时任务" aria-label="Permalink to &quot;长任务与定时任务&quot;">​</a></h1><h2 id="长任务" tabindex="-1">长任务 <a class="header-anchor" href="#长任务" aria-label="Permalink to &quot;长任务&quot;">​</a></h2><p>要做很久的事（整理大量文件、批量处理表格）：</p><ul><li>打开输入框下方的「<strong>长任务</strong>」开关，步数上限放宽，走到上限自动接着做；</li><li>任务每做一步就存一次，程序被关、电脑重启都不会丢。重新打开后，侧栏「任务中心」和对话里会提示「上次没做完」，点「接着做」；</li><li>悬浮球上能看到进度，鼠标停上去可以暂停、停止、插话。</li></ul><h2 id="任务中心" tabindex="-1">任务中心 <a class="header-anchor" href="#任务中心" aria-label="Permalink to &quot;任务中心&quot;">​</a></h2><p>侧栏「任务中心」按<strong>一件事</strong>列出来，每张卡片写着：</p><ul><li><strong>从哪来</strong>：自己发起、手机、钉钉、企业微信、指令中心、定时任务、文件夹监视、PR 自动修复；</li><li><strong>谁让做的</strong>、<strong>按什么授权</strong>（权限和工作区，不是你本人发起的任务才有）；</li><li><strong>跑了几轮</strong>、<strong>用了多少 token</strong>（IT 设了单个任务的上限时显示「已用 / 上限」）；</li><li><strong>状态</strong>：进行中、等你确认、中断、已完成、没做完、已停止。</li></ul><p>上面可以按状态、按来源筛选。进行中的可以暂停、停止；中断的可以「接着做」或「不用了」；点标题或「打开」回到那个对话。</p><p><strong>什么算一件事</strong>：你自己在对话里说一句话，到 AI 停下来为止算一件事——中间排队的话、插话、长任务自动接着做、中断后接着做，都记在这件事下面。AI 停下后你再说话，算新的一件。手机、钉钉、定时任务等每来一次都是新的一件。</p><h2 id="一句话交代好几件事" tabindex="-1">一句话交代好几件事 <a class="header-anchor" href="#一句话交代好几件事" aria-label="Permalink to &quot;一句话交代好几件事&quot;">​</a></h2><p>IT 打开「一句话里的几件事分开做」后，你一次交代好几件互相独立的事（比如编号列出 3 件），发送前会问一句「看起来是 3 件事，要分开做吗？」：</p><ul><li><strong>分开做</strong>：每件事在自己的对话里做（侧栏里是「1/3 · …」「2/3 · …」），原来的对话里有一张汇总卡，看每件做到哪了，点一下进去； 几件事要你确认的操作也合在这张卡里，可以逐条允许或拒绝。「全部允许」只管普通操作，<strong>高危操作仍要一条一条点</strong>。全部做完后，原对话里有一段汇总。</li><li><strong>就当一件做</strong>：照常发送，和以前一样。</li></ul><p>默认一件做完再做下一件；IT 也可以设成同时做 2～3 件（同时做时，改文件这类操作仍然一次一个）。</p><h2 id="钉钉、企业微信里追问" tabindex="-1">钉钉、企业微信里追问 <a class="header-anchor" href="#钉钉、企业微信里追问" aria-label="Permalink to &quot;钉钉、企业微信里追问&quot;">​</a></h2><p>IT 打开「调度」后，你在钉钉或企业微信里交代的事还在办时：</p><ul><li>追问或补充（「顺便加一列合计」）会直接交给正在做的那件，马上回你一句「已补充给正在做的…」，最后结果一起回复；</li><li>问「做到哪了」会按任务记录直接回复进度，不会另开一件事；</li><li>新的事照常排队。</li></ul><p>只会在<strong>你自己</strong>交代的事里找，不会归到别人的任务里。</p><h2 id="看门狗" tabindex="-1">看门狗 <a class="header-anchor" href="#看门狗" aria-label="Permalink to &quot;看门狗&quot;">​</a></h2><p>IT 打开「看门狗」后，AI 一直在忙、却十几分钟没有新进展（没有新操作、计划没推进、没产出文件）时，会弹通知「任务可能卡住了 / 可能跑偏了」，任务中心的卡片上也会标出原因：</p><ul><li>点「<strong>不用管</strong>」：这件事后面不再提醒；</li><li>点「<strong>停止</strong>」：和平时停止一样，已经做完的不会撤回。</li></ul><p>AI 也会收到提醒，通常会换个办法或停下来问你。IT 还打开了「自动停下」的话，提醒过仍没进展的任务会被自动停下，任务中心写着「看门狗：长时间没有进展」。</p><p>编译、跑测试这类要很久的命令执行时、等你确认时、暂停时都不计时，不会被误判。</p><h2 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h2><p>让 AI 盯一个 PR 之后，这个对话就「订阅」了它：CI、评审、合并这些动静会回到这个对话。打开对话右侧的「会话信息」能看到订阅了哪些，点「取消订阅」就不再盯。PR 合并、关闭或盯满 14 天会自动结束。</p><h2 id="定时任务" tabindex="-1">定时任务 <a class="header-anchor" href="#定时任务" aria-label="Permalink to &quot;定时任务&quot;">​</a></h2><p>侧栏「定时任务」→「新建任务」，写一句指令再选频率：</p><table tabindex="0"><thead><tr><th>任务名</th><th>指令</th><th>频率</th></tr></thead><tbody><tr><td>整理昨天的报表</td><td>把共享盘「报表\\昨天」里的 Excel 合并成一张汇总表，放到工作区</td><td>每个工作日 08:30</td></tr><tr><td>清理临时文件</td><td>删掉工作区里 30 天前的临时文件，删之前先列出来给我看</td><td>每周一 09:00</td></tr></tbody></table><p>注意：</p><ul><li><strong>程序要开着</strong>（收在托盘里就行）。关机错过的任务，开机后补跑最近一次，超过 12 小时就跳过；</li><li>需要确认的操作会弹系统通知，可以在通知上直接点允许；<strong>5 分钟没人应答按拒绝处理</strong>；</li><li>新任务可以先勾「<strong>预演（只看不改）</strong>」跑几次，确认没问题再取消勾选；</li><li>也可以设成「文件夹里有新文件」时触发，例如共享盘出现新日报就自动汇总。</li></ul>',29)])])}const c=a(e,[["render",i]]);export{u as __pageData,c as default};
